create extension if not exists pgcrypto;
create table if not exists users(id uuid primary key default gen_random_uuid(),email text unique not null,name text not null,role text not null default 'creator',bio text not null default '',password_hash text not null,room jsonb not null default '{}',created_at timestamptz not null default now());
create table if not exists sessions(token text primary key,user_id uuid not null references users(id) on delete cascade,expires_at timestamptz not null,created_at timestamptz not null default now());
create index if not exists sessions_user_idx on sessions(user_id);
create table if not exists stories(id uuid primary key default gen_random_uuid(),author_id uuid not null references users(id) on delete cascade,title text not null,synopsis text not null default '',genre text not null default 'Contemporáneo',status text not null default 'en progreso',tags jsonb not null default '[]',cover_url text,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists chapters(id uuid primary key default gen_random_uuid(),story_id uuid not null references stories(id) on delete cascade,title text not null,body text not null default '',position integer not null default 1,published boolean not null default false,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create index if not exists chapters_story_idx on chapters(story_id,position);
create table if not exists artworks(id uuid primary key default gen_random_uuid(),author_id uuid not null references users(id) on delete cascade,title text not null,description text not null default '',media_url text not null,created_at timestamptz not null default now());
create table if not exists circles(id uuid primary key default gen_random_uuid(),owner_id uuid not null references users(id) on delete cascade,name text not null,description text not null default '',created_at timestamptz not null default now());
create table if not exists circle_members(circle_id uuid references circles(id) on delete cascade,user_id uuid references users(id) on delete cascade,role text not null default 'member',joined_at timestamptz not null default now(),primary key(circle_id,user_id));
create table if not exists posts(id uuid primary key default gen_random_uuid(),author_id uuid not null references users(id) on delete cascade,body text not null,circle_id uuid references circles(id) on delete set null,created_at timestamptz not null default now());
create table if not exists follows(follower_id uuid references users(id) on delete cascade,following_id uuid references users(id) on delete cascade,created_at timestamptz not null default now(),primary key(follower_id,following_id));
create table if not exists likes(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,target_type text not null,target_id uuid not null,created_at timestamptz not null default now(),unique(user_id,target_type,target_id));
create table if not exists comments(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,target_type text not null,target_id uuid not null,body text not null,created_at timestamptz not null default now());
create table if not exists messages(id uuid primary key default gen_random_uuid(),from_user_id uuid references users(id) on delete cascade,to_user_id uuid references users(id) on delete cascade,body text not null,read boolean not null default false,created_at timestamptz not null default now());
create index if not exists messages_pair_idx on messages(from_user_id,to_user_id,created_at desc);
create table if not exists notifications(id uuid primary key default gen_random_uuid(),user_id uuid references users(id) on delete cascade,type text not null,text text not null,meta jsonb not null default '{}',read boolean not null default false,created_at timestamptz not null default now());
create index if not exists notifications_user_idx on notifications(user_id,created_at desc);
create table if not exists reports(id uuid primary key default gen_random_uuid(),reporter_id uuid references users(id) on delete cascade,target_type text not null,target_id uuid not null,reason text not null,details text not null default '',status text not null default 'open',created_at timestamptz not null default now(),resolved_at timestamptz);
create index if not exists reports_status_idx on reports(status,created_at desc);
